composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      MONGO_URL: "mongodb://{{serviceName}}-mongo:27017/errbit"
      ERRBIT_HOST: {{env.ERRBIT_HOST}}
      SECRET_KEY_BASE: {{env.SECRET_KEY_BASE}}
      ERRBIT_EMAIL_FROM: {{env.ERRBIT_EMAIL_FROM}}
  {{serviceName}}-mongo:
    image: mongo:6
    container_name: {{serviceName}}-mongo
    restart: unless-stopped
